 store.create({identity,question:'准备历史',source:inspection,preparation:'v1'});const lease=store.begin(identity.task_id);store.finish(lease,'failed');const preview_id=randomUUID(),preview_identity={...identity,run_id:randomUUID(),attempt_id:randomUUID(),operation_id:randomUUID()},preferences={skill:'general' as const,prompt:'professional' as const};store.reservePreview(identity.task_id,{version:'1.0',command_id:preview_id,baseline_identity:identity,identity:preview_identity,question:'只准备新候选',preferences});const owner={task_id:identity.task_id,identity:preview_identity,epoch:store.read(identity.task_id)!.epoch,preview_command_id:preview_id};store.savePreparation!(owner,{producer:'describe_business',semantics:null,business:{classification:'MODEL_PROPOSAL',purpose:'准备说明',object:'合成记录',scope:'当前资料',deliverables:[],hypotheses:[],unknowns:[]},framework:null,candidate_plans:[]});store.completePreview(identity.task_id,preview_id,{state:'answered',framework:null,text:'仅为候选说明',failure_code:null});const original=store.read(identity.task_id)!.preparation_snapshots;
 const next=store.revise(identity.task_id,{command_id:randomUUID(),expected_revision:'1',identity:{...identity,revision:'2',run_id:randomUUID(),attempt_id:randomUUID(),operation_id:randomUUID()},question:'用户明确的新问题',preferences});assert.equal(next.version,'1.4');assert.deepEqual(next.preparation_snapshots,[]);assert.deepEqual(next.history![0]!.preparation_snapshots,original);assert.deepEqual(createLocalOpenAnalysisStore({projectRoot:root}).read(identity.task_id),next);
