for(const boundary of ['count','bytes'] as const)test(`PREP-S04 ${boundary}: actual persisted history refuses the next snapshot without deleting old evidence`,async()=>{
 const {mkdtempSync,writeFileSync}=await import('node:fs'),{join}=await import('node:path'),{tmpdir}=await import('node:os'),{DatabaseSync}=await import('node:sqlite'),{createLocalOpenAnalysisStore}=await import('../../../adapters/storage-local/open-analysis.ts'),{compileOpenBusinessProposal}=await import('../../../packages/product-core/open-analysis-context.ts'),{preparationHash}=await import('../../../packages/application/open-analysis-preparation.ts');const root=mkdtempSync(join(process.env.JUANERAI_TEST_EVIDENCE_DIR??tmpdir(),'preparation-limit-'+boundary+'-')),store=createLocalOpenAnalysisStore({projectRoot:root}),identity={task_id:randomUUID(),revision:'1',run_id:randomUUID(),attempt_id:randomUUID(),operation_id:randomUUID(),grant_id:randomUUID(),scope_sha256:taskHash(inspection),config_sha256:'b'.repeat(64)};store.create({identity,question:'合成准备保存边界',source:inspection,preparation:'v1'});const owner={...store.begin(identity.task_id),preview_command_id:null},items=boundary==='bytes'?Array.from({length:16},(_,n)=>String(n)+'界'.repeat(600)):[],business=compileOpenBusinessProposal({purpose:'0',object:'合成记录',scope:'当前资料',deliverables:items,hypotheses:items,unknowns:items});store.savePreparation!(owner,{producer:'describe_business',semantics:null,business,framework:null,candidate_plans:[]});const base=store.read(identity.task_id)!,template=base.preparation_snapshots![0]!,snapshots:typeof template[]=[];let total=2;
 // Valid fixture rows are seeded in the test-owned real SQLite, not claimed as 1000 executed tools.
 for(let n=0;n<1000;n++){const record={...template,snapshot_id:randomUUID(),previous_snapshot_id:snapshots.at(-1)?.snapshot_id??null,business:{...business,purpose:String(n)}};record.content_sha256=preparationHash(record);const size=Buffer.byteLength(JSON.stringify(record))+(n?1:0);if(boundary==='bytes'&&total+size>64*1024*1024)break;snapshots.push(record);total+=size;}
 assert.ok(boundary==='count'?snapshots.length===1000:snapshots.length<1000&&total<=64*1024*1024&&total>63*1024*1024);const fixture={...base,preparation_snapshots:snapshots},digest=taskHash(fixture),db=new DatabaseSync(join(root,'.xanthil/desktop/open-analysis.sqlite'));db.prepare('UPDATE tasks SET body_json=?,body_sha256=? WHERE task_id=?').run(JSON.stringify(fixture),digest,identity.task_id);db.close();
 const reopened=createLocalOpenAnalysisStore({projectRoot:root});assert.equal(reopened.read(identity.task_id)!.preparation_snapshots!.length,snapshots.length);assert.throws(()=>reopened.savePreparation!(owner,{producer:'describe_business',semantics:null,business:{...business,purpose:'the-next-real-snapshot'},framework:null,candidate_plans:[]}),{code:'PREPARATION_LIMIT'});const check=new DatabaseSync(join(root,'.xanthil/desktop/open-analysis.sqlite'),{readOnly:true});assert.equal(check.prepare('SELECT body_sha256 FROM tasks WHERE task_id=?').get(identity.task_id)!.body_sha256,digest);check.close();writeFileSync(join(root,'limit-result.json'),JSON.stringify({boundary,count:snapshots.length,serializedSnapshotBytes:total,unchanged_sha256:digest,physicalModelCalls:0,physicalToolCalls:0}));
});

