 const first=factory({...base,runtime:{run:async(i:OpenAnalysisRun)=>{const call=(name:string,args:any={})=>i.tools.find(t=>t.name===name)!.execute(args,i.signal) as Promise<any>;const r=await call('read_analysis_evidence',{required_plans:[sum,mean]});checkpoint={version:'1.0',turn:1,messages:[{speaker:'user',text:input.question},{speaker:'assistant',text:'',calls:[{id:'owned-read',name:'read_analysis_evidence',arguments:{required_plans:[sum,mean]}}]},{speaker:'tool',call_id:'owned-read',name:'read_analysis_evidence',result:r,failed:false}]};await call('calculate_and_verify',{plan:sum});allowed=false;return {text:'部分合计已完成',tools:[]};}}});
 await assert.rejects(()=>first.run(input),{code:'AUTHORITY_REQUIRED'});allowed=true;assert.equal(proofs.length,1);assert.equal(outcomes.length,0);
 const resumed=(complete:boolean)=>factory({...base,checkpoint,framework:frame,qualifiedSteps:proofs,runtime:{run:async(i:OpenAnalysisRun)=>{const call=(name:string,args:any={})=>i.tools.find(t=>t.name===name)!.execute(args,i.signal) as Promise<any>;const r=await call('read_analysis_evidence',{required_plans:[sum]});assert.deepEqual(r.required_calculations.map((x:any)=>x.status),['verified','missing'],'subset read cannot remove the unfinished mean');const before=checks;await call('read_analysis_evidence');assert.equal(checks,before);if(complete){const r=await call('calculate_and_verify',{plan:mean});assert.equal(r.calculation.value,'11/2');}return {text:'平均需其自身凭证',tools:[]};}}});
 assert.equal((await resumed(false).run(input)).state,'saved');assert.equal(checks,2,'only missing mean is actually consumed on explicit continuation');assert.equal(outcomes.length,1);
