test('OA-RT05 B3: correction is per distinct independently checked accepted step',async()=>{const factory=Reflect.get(application,'createOpenAnalysisApplication'),attempts=new Map<string,number>();let saved:any;const app=factory({runtime:{run:async(i:OpenAnalysisRun)=>{const tool=(name:string)=>i.tools.find(t=>t.name===name)!;for(const operation of ['sum','max','min']){await tool('set_framework').execute({goal:operation,source_id:inspection.sources[0]!.source_id,sheet_id:inspection.sources[0]!.sheets[0]!.sheet_id,operation,column:'B',unit:'count',group_mode:'none'},i.signal);const failed:any=await tool('calculate_and_verify').execute({code:'first'},i.signal);assert.equal(failed.status,'needs_code_correction');assert.equal(failed.remaining_corrections,1);const result:any=await tool('calculate_and_verify').execute({code:'fixed'},i.signal);assert.equal(result.verification.grade,'independent_arithmetic');}return {text:'实际完成三步核验',tools:[]};}},executeCode:async({plan}:any)=>{const count=attempts.get(plan.goal)??0;attempts.set(plan.goal,count+1);if(!count)throw Object.assign(Error('synthetic execution failed'),{code:'PREPARATION_EXECUTION_FAILED'});return {value:{value:plan.operation==='sum'?'11':plan.operation==='max'?'7':'4',rows:2},receipt:{synthetic:true}};},loadSelectedSource:async()=>inspection,isAuthorized:()=>true,saveFramework:async(x:any)=>({saved:true,...x.identity}),verify:verifyOpenAnalysisIntegerSum,saveOutcome:async(x:any)=>{saved=x;return {saved:true,...x.identity,outcome_id:x.outcome_id};}});await app.run({identity:{task_id:randomUUID(),revision:'1',run_id:randomUUID(),attempt_id:randomUUID(),operation_id:randomUUID(),grant_id:randomUUID(),scope_sha256:taskHash(inspection),config_sha256:'b'.repeat(64)},question:'核验总数、最大值和最小值',signal:new AbortController().signal});assert.equal(saved.calculation.value,'4');assert.deepEqual([...attempts.values()],[2,2,2]);});

