test('FM-AX1/A02: proposal preparation compiles actual changed Binding without execution or overwriting accepted state',async()=>{
 const create=Reflect.get(application,'createOpenAnalysisApplication');let writes=0,executes=0,checks=0;
 const identity={task_id:randomUUID(),revision:'1',run_id:randomUUID(),attempt_id:randomUUID(),operation_id:randomUUID(),grant_id:randomUUID(),scope_sha256:taskHash(inspection),config_sha256:'b'.repeat(64)};
 const app=create({proposalOnly:true,proposalHistory:[{question:'之前请先准备方案',clarification:'请再次确认后才绑定。'}],runtime:{run:async(input:OpenAnalysisRun)=>{
  assert.match(input.prompt,/之前请先准备方案/);assert.doesNotMatch(input.prompt,/请再次确认后才绑定/);assert.doesNotMatch(input.prompt,/历史模型回复/);
  assert.match(input.system,/不执行计算/);assert.doesNotMatch(input.system,/再 calculate_and_verify 实际计算|调用explore_with_python生成分析程序|完成核验后用中文说明业务结果|不需要你逐个重复设置框架/);assert.equal(input.tools.some(t=>t.name==='calculate_and_verify'),false);
  await input.tools.find(t=>t.name==='inspect_selected')!.execute({},input.signal);
  await input.tools.find(t=>t.name==='set_framework')!.execute({goal:'改看销售额',source_id:inspection.sources[0]!.source_id,sheet_id:inspection.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column:'A',unit:'元',group_mode:'none'},input.signal);
  return {text:'由数量改为销售额，旧数量成果不作为本版销售额结论。',tools:[]};
 }},loadSelectedSource:async()=>inspection,isAuthorized:()=>true,saveFramework:async x=>{writes++;return {saved:true,...x.identity};},saveCheckpoint:async()=>{writes++;return {saved:true,...identity};},saveOutcome:async x=>{writes++;return {saved:true,outcome_id:x.outcome_id,...x.identity};},executeCode:async()=>{executes++;throw Error('must not execute');},verify:async()=>{checks++;throw Error('must not verify');}});
 const result=await app.run({identity,question:'改看销售额',signal:new AbortController().signal});assert.equal(result.state,'proposal');assert.ok(result.framework);assert.equal(result.framework.plan.column,'A');assert.equal(result.framework.context.proposal.plan.column,'A');assert.equal(result.framework.plan.inspection_sha256,taskHash(inspection));assert.equal(writes,0);assert.equal(executes,0);assert.equal(checks,0);
});
