test('FM-A01: declared calculation conflict blocks actual verification; literal user choice changes physical binding and independently checks new facts',async()=>{
 const identity={task_id:randomUUID(),revision:'1',run_id:randomUUID(),attempt_id:randomUUID(),operation_id:randomUUID(),grant_id:randomUUID(),scope_sha256:taskHash(inspection),config_sha256:'b'.repeat(64)};let checked=0,frame:any;const outcomes:any[]=[];
 const conflict={dimension:'metric',question:'订单金额还是净销售额？',alternatives:['订单金额','净销售额'],resolution_quote:null};
 const create=Reflect.get(application,'createOpenAnalysisApplication');
 const build=(chosen=false)=>create({framework:chosen?frame:null,runtime:{run:async(input:OpenAnalysisRun)=>{const tool=(name:string)=>{const t=input.tools.find(t=>t.name===name);assert.ok(t,`FM-A01: ${name} must enforce business meaning`);return t;};await tool('assess_meaning').execute({definitions:[{dimension:'metric',value:chosen?'净销售额':'订单金额',user_quote:chosen?'本次使用净销售额':null}],conflicts:[{...conflict,resolution_quote:chosen?'本次使用净销售额':null}]},input.signal);await tool('set_framework').execute({goal:'销售核对',source_id:inspection.sources[0]!.source_id,sheet_id:inspection.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column:chosen?'B':'A',unit:'元'},input.signal);const value:any=await tool('calculate_and_verify').execute({},input.signal);if(!chosen){assert.equal(value.status,'needs_information');assert.equal(value.code,'SEMANTIC_CONFLICT');assert.equal(checked,0);await assert.rejects(()=>tool('inspect_selected').execute({},input.signal),{code:'INFORMATION_REQUIRED'});}else{assert.equal(value.calculation.value,'11');assert.equal(value.verification.value,'11');}return {text:chosen?'按本次选定净额核对':'请确认金额口径',tools:[]};}},loadSelectedSource:async()=>inspection,isAuthorized:()=>true,saveFramework:async(x:any)=>{frame=x;return {saved:true,...x.identity};},saveClarification:async(x:any)=>({saved:true,...x.identity}),verify:(...args:any[])=>{checked++;return Reflect.apply(verifyOpenAnalysisIntegerSum,null,args);},saveOutcome:async(x:any)=>{outcomes.push(x);return {saved:true,outcome_id:x.outcome_id,...x.identity};}});
 const unresolved=await build().run({identity,question:'分析销售额',signal:new AbortController().signal});assert.equal(unresolved.state,'waiting');assert.equal(checked,0);assert.equal(outcomes.length,0);assert.equal(frame.context.semantics.conflicts[0].state,'unresolved');const {validateOpenAnalysisContext}=await import('../../../packages/product-core/open-analysis-context.ts');validateOpenAnalysisContext(frame.context,inspection,['分析销售额']);
 const resolved=await build(true).run({identity,question:'本次使用净销售额',signal:new AbortController().signal});assert.equal(resolved.state,'saved');assert.equal(checked,1);assert.equal(outcomes.length,1);assert.equal(outcomes[0].framework.column,'B');assert.equal(frame.context.version,'1.1');assert.equal(frame.context.semantics.conflicts[0].selected,'净销售额');validateOpenAnalysisContext(frame.context,inspection,['分析销售额','本次使用净销售额']);const forged=structuredClone(frame.context);forged.semantics.definitions[0].user_question='模型编造的用户决定';assert.throws(()=>validateOpenAnalysisContext(forged,inspection,['分析销售额','本次使用净销售额']),{code:'CONTEXT_CHANGED'});
});

