test('FM-A03/RT04: qualified declared step is read back on duplicate/resume, never recomputed',async()=>{
 const factory=Reflect.get(application,'createOpenAnalysisApplication'),identity={task_id:randomUUID(),revision:'1',run_id:randomUUID(),attempt_id:randomUUID(),operation_id:randomUUID(),grant_id:randomUUID(),scope_sha256:taskHash(inspection),config_sha256:'b'.repeat(64)},a=randomUUID(),b=randomUUID();let checks=0,frame:any,phase=1;const saved:any[]=[];
 const cfg={runtime:{run:async(i:OpenAnalysisRun)=>{const call=(n:string,x:any={})=>i.tools.find(t=>t.name===n)!.execute(x,i.signal) as Promise<any>;if(phase===1){const step=(id:string,deps:string[],column:string)=>({step_id:id,title:column==='A'?'销售额':'数量',depends_on:deps,hypotheses:[],required_evidence:['当前字段'],limitations:['不证明原因'],plan:{version:'1.0',goal:column==='A'?'销售额':'数量',source_id:inspection.sources[0]!.source_id,sheet_id:inspection.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column,unit:'单位'}});await call('set_analysis_steps',{version:'1.0',steps:[step(a,[],'A'),step(b,[a],'B')]});await call('execute_step',{step_id:a});await call('execute_step',{step_id:b});await call('execute_step',{step_id:a});assert.equal(checks,2,'duplicate qualified step must not perform another independent recheck/computation');}else{const r=await call('execute_step',{step_id:b});assert.equal(r.calculation.value,'11');assert.equal(checks,2,'explicit continuation consumes persisted proof, not a repeat calculation');}return {text:'核验成果',tools:[]};}},loadSelectedSource:async()=>inspection,isAuthorized:()=>true,saveStepEvent:recordStepAdmission,saveFramework:async(value:any)=>{frame=value;return {saved:true as const,...identity};},saveVerifiedStep:async(value:any)=>{saved.push(value);return {saved:true as const,step_id:value.step_id,...identity};},verify:(p:any,c:any,s:any)=>{checks++;return verifyOpenAnalysisIntegerSum(p,c,s);},saveOutcome:async(o:any)=>({saved:true as const,outcome_id:o.outcome_id,...identity})};const input={identity,question:'核对销售额和数量',signal:new AbortController().signal};await factory(cfg).run(input);phase=2;await factory({...cfg,framework:frame,qualifiedSteps:saved}).run(input);assert.equal(checks,2);
});

